import path from "node:path";
import {
  cloudflareTest,
  readD1Migrations,
} from "@cloudflare/vitest-pool-workers";
import { defineConfig } from "vitest/config";

export default defineConfig(async () => {
  // The admin Worker's D1 migrations, generated by drizzle-kit.
  const migrations = await readD1Migrations(
    path.join(import.meta.dirname, "../../apps/admin/migrations"),
  );

  return {
    test: {
      projects: [
        // Plugin schemas: plain Node (reads the vendored files for comparison).
        { test: { name: "plugins", include: ["test/*.test.ts"] } },
        // Tables: round-trips through D1 in workerd.
        {
          plugins: [
            cloudflareTest({
              miniflare: {
                compatibilityDate: "2025-04-14",
                compatibilityFlags: ["nodejs_compat"],
                d1Databases: ["DB"],
                bindings: { TEST_MIGRATIONS: migrations },
              },
            }),
          ],
          test: {
            name: "d1",
            include: ["test/db/**/*.test.ts"],
            setupFiles: ["./test/db/apply-migrations.ts"],
          },
        },
      ],
    },
  };
});
